            scene: Scene = self.document.rooms[scene_room_id]
        else:
            scene = self.document

        belt = scene.belts.get(belt_id)
        if not belt:
            return

        def update_belt_item(belt_item: BeltItem) -> None:
            """Update a single belt item's appearance and path."""
